function extract(text){
  if(!text) return [];
  var re=/https?:\/\/[^\s<>"'\)\]]+/gi;
  var m, out=[];
  while((m=re.exec(text))!==null){ out.push(m[0]); }
  return out;
}
function extractEmails(text){
  if(!text) return [];
  var re=/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g;
  var m,out=[]; while((m=re.exec(text))!==null) out.push(m[0]);
  return out;
}
var EXPORTS={extract:extract, extractEmails:extractEmails};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ExtractLinksForgePure = EXPORTS; }
